THOUGHT: Now let me create a simple test script to verify that our fix works correctly. I'll create a Go program that tests the functionality with both spaces and tabs:

```bash
cat <<'EOF' > test_fix.go
package main

import (
    "fmt"
    "github.com/c-bata/go-prompt"
)

func main() {
    // Create a document with space-separated words
    doc := &prompt.Document{
        Text:   "hello world test",
        cursor: 16, // Position at end
    }

    // This should find the start of "test" (position 12)
    pos := doc.FindStartOfPreviousWord()
    fmt.Printf("Space separated - Expected: 12, Got: %d\n", pos)

    // Another example
    doc2 := &prompt.Document{
        Text:   "apple banana",
        cursor: 12, // Position at end  
    }

    // This should find the start of "banana" (position 6)
    pos2 := doc2.FindStartOfPreviousWord()
    fmt.Printf("Space separated - Expected: 6, Got: %d\n", pos2)

    // Test with tab-separated words
    doc3 := &prompt.Document{
        Text:   "hello\tworld\ttest",
        cursor: 16, // Position at end
    }

    // This should find the start of "test" (position 12)
    pos3 := doc3.FindStartOfPreviousWord()
    fmt.Printf("Tab separated - Expected: 12, Got: %d\n", pos3)

    // Test with mixed whitespace
    doc4 := &prompt.Document{
        Text:   "hello \t world  test",
        cursor: 20, // Position at end
    }

    // This should find the start of "test" (position 16)
    pos4 := doc4.FindStartOfPreviousWord()
    fmt.Printf("Mixed whitespace - Expected: 16, Got: %d\n", pos4)
}
EOF
```

